def set_age(age):
    if age < 0:
        raise ValueError(f"age cannot be {age}")
    return age

try:
    set_age(-5)
except ValueError as e:
    print(e)

class InsufficientFunds(Exception):
    pass

def withdraw(balance, x):
    if x > balance:
        raise InsufficientFunds(f"need {x - balance} more")
    return balance - x

try:
    withdraw(100, 150)
except InsufficientFunds as e:
    print(e)

def load(cfg):
    try:
        return cfg["port"]
    except KeyError as e:
        raise RuntimeError("no port in the settings") from e

try:
    load({})
except RuntimeError as e:
    print(e, "| cause:", repr(e.__cause__))

def mean(xs):
    assert len(xs) > 0, "the list must not be empty"   # programmer error
    return sum(xs) / len(xs)

def parse_age(text):
    age = int(text)
    if age < 0:
        raise ValueError("age < 0")                  # data error
    return age

print(mean([1, 2, 3]), parse_age("20"))
